class Solution {
    public long maxMatrixSum(int[][] matrix){
        long sum=0;
        int negatives=0,minimum=Integer.MAX_VALUE;
        for(int[] row:matrix)for(int value:row){
            if(value<0)negatives++;
            int absolute=Math.abs(value);
            sum+=absolute;
            minimum=Math.min(minimum,absolute);
        }
        return negatives%2==0?sum:sum-2L*minimum;
    }
}

code.kotlin:
class Solution {
    fun maxMatrixSum(matrix:Array<IntArray>):Long{
        var sum=0L;
        var negatives=0;
        var minimum=Int.MAX_VALUE;
        for(row in matrix)for(value in row){
            if(value<0)negatives++;
            val absolute=kotlin.math.abs(value);
            sum+=absolute;
            minimum=minOf(minimum,absolute)
        };
        return if(negatives%2==0)sum else sum-2L*minimum
    }
}

